  "Derived from roles, station and assignments. Access is denied unless explicitly granted.": "ਭੂਮਿਕਾਵਾਂ, ਥਾਣੇ ਅਤੇ ਸੌਂਪੇ ਕੰਮਾਂ ਤੋਂ ਨਿਰਧਾਰਿਤ। ਜਦੋਂ ਤੱਕ ਸਪਸ਼ਟ ਤੌਰ 'ਤੇ ਦਿੱਤੀ ਨਾ ਜਾਵੇ, ਪਹੁੰਚ ਨਹੀਂ ਮਿਲਦੀ।",
