  "This will close the case. Open tasks are not closed automatically. The case can be reopened if the workflow allows.": "ਇਸ ਨਾਲ ਕੇਸ ਬੰਦ ਹੋ ਜਾਵੇਗਾ। ਖੁੱਲ੍ਹੇ ਕੰਮ ਆਪਣੇ-ਆਪ ਬੰਦ ਨਹੀਂ ਹੁੰਦੇ। ਜੇ ਕਾਰਜ-ਪ੍ਰਵਾਹ ਆਗਿਆ ਦੇਵੇ ਤਾਂ ਕੇਸ ਦੁਬਾਰਾ ਖੋਲ੍ਹਿਆ ਜਾ ਸਕਦਾ ਹੈ।",
