  "Officer-written summary. The original statement and transcripts are kept separately and are not changed by this field.": "ਅਧਿਕਾਰੀ ਵੱਲੋਂ ਲਿਖਿਆ ਸਾਰ। ਮੂਲ ਬਿਆਨ ਅਤੇ ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਵੱਖਰੇ ਰੱਖੇ ਜਾਂਦੇ ਹਨ ਅਤੇ ਇਸ ਖੇਤਰ ਨਾਲ ਨਹੀਂ ਬਦਲਦੇ।",
