  "Only record \"submitted\" or \"filed\" when you hold a verified response from an authorized external system. FirstRecord has no automatic integration with official systems; this entry is manual and will be audited under your name.": "\"ਜਮ੍ਹਾਂ ਕੀਤਾ\" ਜਾਂ \"ਦਰਜ ਕੀਤਾ\" ਸਿਰਫ਼ ਉਦੋਂ ਹੀ ਦਰਜ ਕਰੋ ਜਦੋਂ ਤੁਹਾਡੇ ਕੋਲ ਕਿਸੇ ਅਧਿਕਾਰਤ ਬਾਹਰੀ ਸਿਸਟਮ ਤੋਂ ਪ੍ਰਮਾਣਿਤ ਜਵਾਬ ਹੋਵੇ। FirstRecord ਦਾ ਅਧਿਕਾਰਤ ਸਿਸਟਮਾਂ ਨਾਲ ਕੋਈ ਸਵੈਚਾਲਿਤ ਏਕੀਕਰਨ ਨਹੀਂ ਹੈ; ਇਹ ਐਂਟਰੀ ਹੱਥੀਂ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਤੁਹਾਡੇ ਨਾਮ ਹੇਠ ਆਡਿਟ ਕੀਤੀ ਜਾਵੇਗੀ।",
