  "Transcription uncertainty": "ਟ੍ਰਾਂਸਕ੍ਰਿਪਸ਼ਨ ਵਿੱਚ ਅਨਿਸ਼ਚਿਤਤਾ",
  "Transcript confirmed": "ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਦੀ ਪੁਸ਼ਟੀ ਹੋ ਗਈ",
