  "e.g. Name at 02:14 unclear in recording": "ਜਿਵੇਂ ਰਿਕਾਰਡਿੰਗ ਵਿੱਚ 02:14 'ਤੇ ਨਾਮ ਸਪਸ਼ਟ ਨਹੀਂ",
  "Report progress": "ਰਿਪੋਰਟ ਦੀ ਪ੍ਰਗਤੀ",
  "Preferences": "ਤਰਜੀਹਾਂ",
  "Mark all as read": "ਸਭ ਨੂੰ ਪੜ੍ਹਿਆ ਚਿੰਨ੍ਹਿਤ ਕਰੋ",
