  "Notifications": "ਸੂਚਨਾਵਾਂ",
  "Assignments, review requests, reminders and status changes. Previews never include statement content.": "ਕੰਮ ਸੌਂਪਣ, ਸਮੀਖਿਆ ਦੀਆਂ ਬੇਨਤੀਆਂ, ਯਾਦ-ਦਹਾਨੀਆਂ ਅਤੇ ਸਥਿਤੀ ਵਿੱਚ ਬਦਲਾਅ। ਝਲਕਾਂ ਵਿੱਚ ਕਦੇ ਵੀ ਬਿਆਨ ਦੀ ਸਮੱਗਰੀ ਸ਼ਾਮਲ ਨਹੀਂ ਹੁੰਦੀ।",
  "Filter notifications": "ਸੂਚਨਾਵਾਂ ਫ਼ਿਲਟਰ ਕਰੋ",
