  "Searches case references, case titles and task titles you have access to. Statement content is never searched here.": "ਉਹ ਕੇਸ ਹਵਾਲੇ, ਕੇਸ ਸਿਰਲੇਖ ਅਤੇ ਕੰਮਾਂ ਦੇ ਸਿਰਲੇਖ ਖੋਜਦਾ ਹੈ ਜਿਨ੍ਹਾਂ ਤੱਕ ਤੁਹਾਡੀ ਪਹੁੰਚ ਹੈ। ਬਿਆਨ ਦੀ ਸਮੱਗਰੀ ਇੱਥੇ ਕਦੇ ਨਹੀਂ ਖੋਜੀ ਜਾਂਦੀ।",
