  "Try a case reference such as CNT/2026, or words from a case or task title.": "CNT/2026 ਵਰਗਾ ਕੋਈ ਕੇਸ ਹਵਾਲਾ, ਜਾਂ ਕਿਸੇ ਕੇਸ ਜਾਂ ਕੰਮ ਦੇ ਸਿਰਲੇਖ ਦੇ ਸ਼ਬਦ ਅਜ਼ਮਾਓ।",
  "Check the spelling or try a shorter reference. Only records you have access to are shown.": "ਸ਼ਬਦ-ਜੋੜ ਜਾਂਚੋ ਜਾਂ ਛੋਟਾ ਹਵਾਲਾ ਅਜ਼ਮਾਓ। ਸਿਰਫ਼ ਉਹੀ ਰਿਕਾਰਡ ਦਿਖਾਏ ਜਾਂਦੇ ਹਨ ਜਿਨ੍ਹਾਂ ਤੱਕ ਤੁਹਾਡੀ ਪਹੁੰਚ ਹੈ।",
