  "Browse statements, transcripts, drafts, reviews, notes, attachments and audit history you are authorized to see. Lists show metadata only; open a record to view its content (access is logged).": "ਉਹ ਬਿਆਨ, ਟ੍ਰਾਂਸਕ੍ਰਿਪਟਾਂ, ਡਰਾਫ਼ਟ, ਸਮੀਖਿਆਵਾਂ, ਨੋਟ, ਅਟੈਚਮੈਂਟ ਅਤੇ ਆਡਿਟ ਇਤਿਹਾਸ ਵੇਖੋ ਜਿਨ੍ਹਾਂ ਨੂੰ ਵੇਖਣ ਲਈ ਤੁਸੀਂ ਅਧਿਕਾਰਤ ਹੋ। ਸੂਚੀਆਂ ਵਿੱਚ ਸਿਰਫ਼ ਮੈਟਾਡਾਟਾ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ; ਸਮੱਗਰੀ ਵੇਖਣ ਲਈ ਰਿਕਾਰਡ ਖੋਲ੍ਹੋ (ਪਹੁੰਚ ਲੌਗ ਕੀਤੀ ਜਾਂਦੀ ਹੈ)।",
