  "No case data in your scope": "ਤੁਹਾਡੇ ਦਾਇਰੇ ਵਿੱਚ ਕੋਈ ਕੇਸ ਡਾਟਾ ਨਹੀਂ",
  "Your role does not include access to case records, so case reports are not available. Technical and security activity is available in the Records audit log.": "ਤੁਹਾਡੀ ਭੂਮਿਕਾ ਵਿੱਚ ਕੇਸ ਰਿਕਾਰਡਾਂ ਤੱਕ ਪਹੁੰਚ ਸ਼ਾਮਲ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ ਕੇਸ ਰਿਪੋਰਟਾਂ ਉਪਲਬਧ ਨਹੀਂ ਹਨ। ਤਕਨੀਕੀ ਅਤੇ ਸੁਰੱਖਿਆ ਗਤੀਵਿਧੀ ਰਿਕਾਰਡ ਆਡਿਟ ਲੌਗ ਵਿੱਚ ਉਪਲਬਧ ਹੈ।",
