  "The user is signed out everywhere and cannot sign in until reactivated. Their records and history are kept.": "ਵਰਤੋਂਕਾਰ ਹਰ ਥਾਂ ਤੋਂ ਸਾਈਨ ਆਊਟ ਹੋ ਜਾਂਦਾ ਹੈ ਅਤੇ ਮੁੜ ਸਰਗਰਮ ਹੋਣ ਤੱਕ ਸਾਈਨ ਇਨ ਨਹੀਂ ਕਰ ਸਕਦਾ। ਉਸ ਦੇ ਰਿਕਾਰਡ ਅਤੇ ਇਤਿਹਾਸ ਰੱਖੇ ਜਾਂਦੇ ਹਨ।",
  "Deactivate account": "ਖਾਤਾ ਅਕਿਰਿਆਸ਼ੀਲ ਕਰੋ",
  "Use when the person leaves the station. The user is signed out and cannot sign in. Records they created remain attributed to them. This can be reversed.": "ਉਦੋਂ ਵਰਤੋ ਜਦੋਂ ਵਿਅਕਤੀ ਥਾਣਾ ਛੱਡ ਜਾਵੇ। ਵਰਤੋਂਕਾਰ ਸਾਈਨ ਆਊਟ ਹੋ ਜਾਂਦਾ ਹੈ ਅਤੇ ਸਾਈਨ ਇਨ ਨਹੀਂ ਕਰ ਸਕਦਾ। ਉਸ ਵੱਲੋਂ ਬਣਾਏ ਰਿਕਾਰਡ ਉਸੇ ਦੇ ਨਾਮ 'ਤੇ ਰਹਿੰਦੇ ਹਨ। ਇਸ ਨੂੰ ਵਾਪਸ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।",
  "Security": "ਸੁਰੱਖਿਆ",
  "Unlock account": "ਖਾਤਾ ਅਨਲੌਕ ਕਰੋ",
  "Clear the temporary lockout caused by repeated failed sign-ins.": "ਵਾਰ-ਵਾਰ ਅਸਫਲ ਸਾਈਨ-ਇਨ ਕਾਰਨ ਲੱਗਿਆ ਆਰਜ਼ੀ ਲੌਕ ਹਟਾਓ।",
  "Sign out {count} session": "{count} ਸੈਸ਼ਨ ਸਾਈਨ ਆਊਟ ਕਰੋ",
  "Sign out {count} sessions": "{count} ਸੈਸ਼ਨ ਸਾਈਨ ਆਊਟ ਕਰੋ",
  "All active sessions for this user will end immediately.": "ਇਸ ਵਰਤੋਂਕਾਰ ਦੇ ਸਾਰੇ ਸਰਗਰਮ ਸੈਸ਼ਨ ਤੁਰੰਤ ਖ਼ਤਮ ਹੋ ਜਾਣਗੇ।",
  "Change your own password under": "ਆਪਣਾ ਪਾਸਵਰਡ ਇੱਥੇ ਬਦਲੋ:",
  "Settings → Profile": "ਸੈਟਿੰਗਾਂ → ਪ੍ਰੋਫ਼ਾਈਲ",
  "The new role will have {count} permission.": "ਨਵੀਂ ਭੂਮਿਕਾ ਕੋਲ {count} ਅਨੁਮਤੀ ਹੋਵੇਗੀ।",
  "The new role will have {count} permissions.": "ਨਵੀਂ ਭੂਮਿਕਾ ਕੋਲ {count} ਅਨੁਮਤੀਆਂ ਹੋਣਗੀਆਂ।",
  "No permission changes selected.": "ਅਨੁਮਤੀਆਂ ਵਿੱਚ ਕੋਈ ਬਦਲਾਅ ਨਹੀਂ ਚੁਣਿਆ ਗਿਆ।",
  "This changes access for every user with this role, effective on their next request.": "ਇਸ ਨਾਲ ਇਸ ਭੂਮਿਕਾ ਵਾਲੇ ਹਰ ਵਰਤੋਂਕਾਰ ਦੀ ਪਹੁੰਚ ਬਦਲ ਜਾਂਦੀ ਹੈ, ਜੋ ਉਨ੍ਹਾਂ ਦੀ ਅਗਲੀ ਬੇਨਤੀ ਤੋਂ ਲਾਗੂ ਹੁੰਦੀ ਹੈ।",
  "Added ({count})": "ਜੋੜੀਆਂ ਗਈਆਂ ({count})",
  "Removed ({count})": "ਹਟਾਈਆਂ ਗਈਆਂ ({count})",
  "Warning: you are granting the System Administrator role access to case or statement content. By default, technical administrators should not see statement content. Only proceed if this is authorized by policy.": "ਚੇਤਾਵਨੀ: ਤੁਸੀਂ ਸਿਸਟਮ ਪ੍ਰਸ਼ਾਸਕ ਭੂਮਿਕਾ ਨੂੰ ਕੇਸ ਜਾਂ ਬਿਆਨ ਦੀ ਸਮੱਗਰੀ ਤੱਕ ਪਹੁੰਚ ਦੇ ਰਹੇ ਹੋ। ਮੂਲ ਰੂਪ ਵਿੱਚ, ਤਕਨੀਕੀ ਪ੍ਰਸ਼ਾਸਕਾਂ ਨੂੰ ਬਿਆਨ ਦੀ ਸਮੱਗਰੀ ਨਹੀਂ ਵੇਖਣੀ ਚਾਹੀਦੀ। ਸਿਰਫ਼ ਤਾਂ ਹੀ ਅੱਗੇ ਵਧੋ ਜੇ ਨੀਤੀ ਅਨੁਸਾਰ ਇਸ ਦੀ ਆਗਿਆ ਹੈ।",
  "Create role?": "ਕੀ ਭੂਮਿਕਾ ਬਣਾਉਣੀ ਹੈ?",
  "Change role permissions?": "ਕੀ ਭੂਮਿਕਾ ਦੀਆਂ ਅਨੁਮਤੀਆਂ ਬਦਲਣੀਆਂ ਹਨ?",
  "Granting content access to System Administrators removes the default separation between technical and case access.": "ਸਿਸਟਮ ਪ੍ਰਸ਼ਾਸਕਾਂ ਨੂੰ ਸਮੱਗਰੀ ਤੱਕ ਪਹੁੰਚ ਦੇਣ ਨਾਲ ਤਕਨੀਕੀ ਅਤੇ ਕੇਸ ਪਹੁੰਚ ਵਿਚਕਾਰ ਮੂਲ ਵਖਰੇਵਾਂ ਖ਼ਤਮ ਹੋ ਜਾਂਦਾ ਹੈ।",
  "you don't hold this": "ਇਹ ਤੁਹਾਡੇ ਕੋਲ ਨਹੀਂ ਹੈ",
  "{count} selected": "{count} ਚੁਣੇ ਗਏ",
  "No unsaved changes": "ਕੋਈ ਅਣਸੇਵ ਬਦਲਾਅ ਨਹੀਂ",
  "{added} to add, {removed} to remove": "{added} ਜੋੜਨੀਆਂ, {removed} ਹਟਾਉਣੀਆਂ",
  "Save permissions": "ਅਨੁਮਤੀਆਂ ਸੇਵ ਕਰੋ",
  "Temporary password": "ਆਰਜ਼ੀ ਪਾਸਵਰਡ",
  "Generate": "ਤਿਆਰ ਕਰੋ",
  "At least 12 characters with letters and numbers. The user must change it at first sign-in. Share it through a secure channel — it is not shown again.": "ਘੱਟੋ-ਘੱਟ 12 ਅੱਖਰ, ਅੱਖਰਾਂ ਅਤੇ ਅੰਕਾਂ ਸਮੇਤ। ਵਰਤੋਂਕਾਰ ਨੂੰ ਪਹਿਲੇ ਸਾਈਨ-ਇਨ 'ਤੇ ਇਸ ਨੂੰ ਬਦਲਣਾ ਲਾਜ਼ਮੀ ਹੈ। ਇਸ ਨੂੰ ਕਿਸੇ ਸੁਰੱਖਿਅਤ ਮਾਧਿਅਮ ਰਾਹੀਂ ਸਾਂਝਾ ਕਰੋ — ਇਹ ਦੁਬਾਰਾ ਨਹੀਂ ਦਿਖਾਇਆ ਜਾਂਦਾ।",
  "Select a role": "ਕੋਈ ਭੂਮਿਕਾ ਚੁਣੋ",
  "Only roles whose permissions you hold yourself are listed.": "ਸਿਰਫ਼ ਉਹ ਭੂਮਿਕਾਵਾਂ ਸੂਚੀਬੱਧ ਹਨ ਜਿਨ੍ਹਾਂ ਦੀਆਂ ਅਨੁਮਤੀਆਂ ਤੁਹਾਡੇ ਕੋਲ ਖ਼ੁਦ ਹਨ।",
  "Create user": "ਵਰਤੋਂਕਾਰ ਬਣਾਓ",
  "Save account changes?": "ਕੀ ਖਾਤੇ ਦੇ ਬਦਲਾਅ ਸੇਵ ਕਰਨੇ ਹਨ?",
  "Changing a role or station signs the user out of all sessions and takes effect immediately. This change is recorded in the audit log.": "ਭੂਮਿਕਾ ਜਾਂ ਥਾਣਾ ਬਦਲਣ ਨਾਲ ਵਰਤੋਂਕਾਰ ਸਾਰੇ ਸੈਸ਼ਨਾਂ ਤੋਂ ਸਾਈਨ ਆਊਟ ਹੋ ਜਾਂਦਾ ਹੈ ਅਤੇ ਇਹ ਤੁਰੰਤ ਲਾਗੂ ਹੁੰਦਾ ਹੈ। ਇਹ ਬਦਲਾਅ ਆਡਿਟ ਲੌਗ ਵਿੱਚ ਦਰਜ ਹੁੰਦਾ ਹੈ।",
  "Save changes": "ਬਦਲਾਅ ਸੇਵ ਕਰੋ",
