  "No station": "ਕੋਈ ਥਾਣਾ ਨਹੀਂ",
  "Reason (recorded in audit log)": "ਕਾਰਨ (ਆਡਿਟ ਲੌਗ ਵਿੱਚ ਦਰਜ ਹੁੰਦਾ ਹੈ)",
