  "Email": "ਈਮੇਲ",
  "Badge / employee number": "ਬੈਜ / ਕਰਮਚਾਰੀ ਨੰਬਰ",
  "No station (System Administrator only)": "ਕੋਈ ਥਾਣਾ ਨਹੀਂ (ਸਿਰਫ਼ ਸਿਸਟਮ ਪ੍ਰਸ਼ਾਸਕ)",
  "Please change your password": "ਕਿਰਪਾ ਕਰਕੇ ਆਪਣਾ ਪਾਸਵਰਡ ਬਦਲੋ",
