  "Current password": "ਮੌਜੂਦਾ ਪਾਸਵਰਡ",
  "Notification preferences": "ਸੂਚਨਾ ਤਰਜੀਹਾਂ",
  "In-app notifications never include statement content — only references and task titles.": "ਐਪ ਵਿੱਚ ਸੂਚਨਾਵਾਂ ਵਿੱਚ ਕਦੇ ਵੀ ਬਿਆਨ ਦੀ ਸਮੱਗਰੀ ਸ਼ਾਮਲ ਨਹੀਂ ਹੁੰਦੀ — ਸਿਰਫ਼ ਹਵਾਲੇ ਅਤੇ ਕੰਮਾਂ ਦੇ ਸਿਰਲੇਖ।",
