  "External delivery": "ਬਾਹਰੀ ਡਿਲੀਵਰੀ",
  "Email copies of notifications": "ਸੂਚਨਾਵਾਂ ਦੀਆਂ ਈਮੇਲ ਕਾਪੀਆਂ",
  "SMS alerts": "SMS ਅਲਰਟ",
  "No email or SMS provider is configured for this deployment, so only in-app notifications are delivered. Nothing is sent externally.": "ਇਸ ਡਿਪਲਾਇਮੈਂਟ ਲਈ ਕੋਈ ਈਮੇਲ ਜਾਂ SMS ਪ੍ਰਦਾਤਾ ਸੰਰਚਿਤ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ ਸਿਰਫ਼ ਐਪ ਵਿੱਚ ਸੂਚਨਾਵਾਂ ਹੀ ਭੇਜੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਬਾਹਰ ਕੁਝ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ।",
  "No email provider is configured for this deployment, so only in-app notifications are delivered. Nothing is sent externally.": "ਇਸ ਡਿਪਲਾਇਮੈਂਟ ਲਈ ਕੋਈ ਈਮੇਲ ਪ੍ਰਦਾਤਾ ਸੰਰਚਿਤ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ ਸਿਰਫ਼ ਐਪ ਵਿੱਚ ਸੂਚਨਾਵਾਂ ਹੀ ਭੇਜੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਬਾਹਰ ਕੁਝ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ।",
  "No SMS provider is configured for this deployment, so only in-app notifications are delivered. Nothing is sent externally.": "ਇਸ ਡਿਪਲਾਇਮੈਂਟ ਲਈ ਕੋਈ SMS ਪ੍ਰਦਾਤਾ ਸੰਰਚਿਤ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ ਸਿਰਫ਼ ਐਪ ਵਿੱਚ ਸੂਚਨਾਵਾਂ ਹੀ ਭੇਜੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਬਾਹਰ ਕੁਝ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ।",
  "Save preferences": "ਤਰਜੀਹਾਂ ਸੇਵ ਕਰੋ",
  "Station not found": "ਥਾਣਾ ਨਹੀਂ ਮਿਲਿਆ",
  "Station profile": "ਥਾਣਾ ਪ੍ਰੋਫ਼ਾਈਲ",
  "Station code {code} — the code is part of case references and cannot be changed here.": "ਥਾਣਾ ਕੋਡ {code} — ਇਹ ਕੋਡ ਕੇਸ ਹਵਾਲਿਆਂ ਦਾ ਹਿੱਸਾ ਹੈ ਅਤੇ ਇੱਥੇ ਬਦਲਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ।",
  "Update station profile?": "ਕੀ ਥਾਣਾ ਪ੍ਰੋਫ਼ਾਈਲ ਅੱਪਡੇਟ ਕਰਨਾ ਹੈ?",
  "The station profile is shown to all staff of this station.": "ਥਾਣਾ ਪ੍ਰੋਫ਼ਾਈਲ ਇਸ ਥਾਣੇ ਦੇ ਸਾਰੇ ਸਟਾਫ਼ ਨੂੰ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ।",
  "Station name": "ਥਾਣੇ ਦਾ ਨਾਮ",
