  "Tokens:": "ਟੋਕਨ:",
  "station code": "ਥਾਣਾ ਕੋਡ",
  "year": "ਸਾਲ",
  "month": "ਮਹੀਨਾ",
  "sequence padded to 5 digits (required).": "5 ਅੰਕਾਂ ਤੱਕ ਭਰਿਆ ਕ੍ਰਮ ਨੰਬਰ (ਲਾਜ਼ਮੀ)।",
  "Sequence reset": "ਕ੍ਰਮ ਰੀਸੈੱਟ",
  "Restart at 1 every calendar year": "ਹਰ ਕੈਲੰਡਰ ਸਾਲ 1 ਤੋਂ ਮੁੜ ਸ਼ੁਰੂ ਕਰੋ",
  "Never restart": "ਕਦੇ ਮੁੜ ਸ਼ੁਰੂ ਨਾ ਕਰੋ",
  "Next reference preview:": "ਅਗਲੇ ਹਵਾਲੇ ਦੀ ਝਲਕ:",
  "Format must include a {SEQ} token.": "ਫ਼ਾਰਮੈਟ ਵਿੱਚ {SEQ} ਟੋਕਨ ਸ਼ਾਮਲ ਹੋਣਾ ਲਾਜ਼ਮੀ ਹੈ।",
  "Save as a new template version?": "ਕੀ ਨਵੇਂ ਟੈਂਪਲੇਟ ਸੰਸਕਰਣ ਵਜੋਂ ਸੇਵ ਕਰਨਾ ਹੈ?",
  "A new template version is created and used for new drafts. Existing drafts keep the version they were created with.": "ਇੱਕ ਨਵਾਂ ਟੈਂਪਲੇਟ ਸੰਸਕਰਣ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਨਵੇਂ ਡਰਾਫ਼ਟਾਂ ਲਈ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ। ਮੌਜੂਦਾ ਡਰਾਫ਼ਟ ਉਹੀ ਸੰਸਕਰਣ ਰੱਖਦੇ ਹਨ ਜਿਸ ਨਾਲ ਉਹ ਬਣਾਏ ਗਏ ਸਨ।",
  "Save new version": "ਨਵਾਂ ਸੰਸਕਰਣ ਸੇਵ ਕਰੋ",
  "Template name": "ਟੈਂਪਲੇਟ ਦਾ ਨਾਮ",
  "Jurisdiction": "ਅਧਿਕਾਰ-ਖੇਤਰ",
  "core field": "ਮੁੱਖ ਖੇਤਰ",
  "custom field": "ਕਸਟਮ ਖੇਤਰ",
  "Remove field {label}": "ਖੇਤਰ {label} ਹਟਾਓ",
  "Label": "ਲੇਬਲ",
