  "Long text": "ਲੰਮਾ ਪਾਠ",
  "Filled by": "ਕੌਣ ਭਰਦਾ ਹੈ",
  "Assistant draft (human-reviewed)": "ਸਹਾਇਕ ਦਾ ਡਰਾਫ਼ਟ (ਮਨੁੱਖ ਵੱਲੋਂ ਸਮੀਖਿਆ)",
  "Officer only": "ਸਿਰਫ਼ ਅਧਿਕਾਰੀ",
