  "Guidance for staff": "ਸਟਾਫ਼ ਲਈ ਮਾਰਗਦਰਸ਼ਨ",
  "Add custom field": "ਕਸਟਮ ਖੇਤਰ ਜੋੜੋ",
  "Save case workflow?": "ਕੀ ਕੇਸ ਕਾਰਜ-ਪ੍ਰਵਾਹ ਸੇਵ ਕਰਨਾ ਹੈ?",
  "Save task workflow?": "ਕੀ ਕੰਮ ਕਾਰਜ-ਪ੍ਰਵਾਹ ਸੇਵ ਕਰਨਾ ਹੈ?",
  "The new workflow applies immediately to all status changes. Existing records keep their current status. This change is audited.": "ਨਵਾਂ ਕਾਰਜ-ਪ੍ਰਵਾਹ ਸਾਰੇ ਸਥਿਤੀ ਬਦਲਾਵਾਂ 'ਤੇ ਤੁਰੰਤ ਲਾਗੂ ਹੁੰਦਾ ਹੈ। ਮੌਜੂਦਾ ਰਿਕਾਰਡ ਆਪਣੀ ਮੌਜੂਦਾ ਸਥਿਤੀ ਬਰਕਰਾਰ ਰੱਖਦੇ ਹਨ। ਇਸ ਬਦਲਾਅ ਦਾ ਆਡਿਟ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
  "Save workflow": "ਕਾਰਜ-ਪ੍ਰਵਾਹ ਸੇਵ ਕਰੋ",
  "Workflow name": "ਕਾਰਜ-ਪ੍ਰਵਾਹ ਦਾ ਨਾਮ",
  "States": "ਸਥਿਤੀਆਂ",
  "The first state is used for new records. At least one state must be a “done” state. States in use cannot be removed.": "ਪਹਿਲੀ ਸਥਿਤੀ ਨਵੇਂ ਰਿਕਾਰਡਾਂ ਲਈ ਵਰਤੀ ਜਾਂਦੀ ਹੈ। ਘੱਟੋ-ਘੱਟ ਇੱਕ ਸਥਿਤੀ “ਪੂਰਾ” ਸਥਿਤੀ ਹੋਣੀ ਲਾਜ਼ਮੀ ਹੈ। ਵਰਤੋਂ ਵਿੱਚ ਸਥਿਤੀਆਂ ਹਟਾਈਆਂ ਨਹੀਂ ਜਾ ਸਕਦੀਆਂ।",
  "{count} in use": "{count} ਵਰਤੋਂ ਵਿੱਚ",
  "Done": "ਪੂਰਾ",
  "Colour": "ਰੰਗ",
  "Move {label} up": "{label} ਨੂੰ ਉੱਪਰ ਲਿਜਾਓ",
  "Move {label} down": "{label} ਨੂੰ ਹੇਠਾਂ ਲਿਜਾਓ",
