  "Allowed transitions": "ਆਗਿਆ ਪ੍ਰਾਪਤ ਤਬਦੀਲੀਆਂ",
  "Rows are the current state; tick each state it may move to.": "ਕਤਾਰਾਂ ਮੌਜੂਦਾ ਸਥਿਤੀ ਹਨ; ਹਰ ਉਸ ਸਥਿਤੀ 'ਤੇ ਨਿਸ਼ਾਨ ਲਾਓ ਜਿਸ ਵਿੱਚ ਇਹ ਜਾ ਸਕਦੀ ਹੈ।",
  "Transition matrix: from state (rows) to state (columns)": "ਤਬਦੀਲੀ ਮੈਟ੍ਰਿਕਸ: ਕਿਸ ਸਥਿਤੀ ਤੋਂ (ਕਤਾਰਾਂ) ਕਿਸ ਸਥਿਤੀ ਤੱਕ (ਕਾਲਮ)",
  "From ↓ / To →": "ਤੋਂ ↓ / ਤੱਕ →",
