  "Save case workflow": "ਕੇਸ ਕਾਰਜ-ਪ੍ਰਵਾਹ ਸੇਵ ਕਰੋ",
  "Save task workflow": "ਕੰਮ ਕਾਰਜ-ਪ੍ਰਵਾਹ ਸੇਵ ਕਰੋ",
  "No catalogue entries matched the statement.": "ਸੂਚੀ ਦੀ ਕੋਈ ਐਂਟਰੀ ਬਿਆਨ ਨਾਲ ਮੇਲ ਨਹੀਂ ਖਾਂਦੀ।",
  "{added} new suggestion(s); {total} matched in total.": "{added} ਨਵੇਂ ਸੁਝਾਅ; ਕੁੱਲ {total} ਮੇਲ ਖਾਂਦੇ।",
  "Provision selected.": "ਧਾਰਾ ਚੁਣੀ ਗਈ।",
  "Provision added and selected.": "ਧਾਰਾ ਜੋੜੀ ਅਤੇ ਚੁਣੀ ਗਈ।",
  "Provision rejected.": "ਧਾਰਾ ਰੱਦ ਕੀਤੀ ਗਈ।",
  "Decision undone.": "ਫ਼ੈਸਲਾ ਵਾਪਸ ਲਿਆ ਗਿਆ।",
  "Saved as draft version {version}.": "ਡਰਾਫ਼ਟ ਸੰਸਕਰਣ {version} ਵਜੋਂ ਸੇਵ ਕੀਤਾ ਗਿਆ।",
  "The draft already lists these provisions.": "ਡਰਾਫ਼ਟ ਵਿੱਚ ਇਹ ਧਾਰਾਵਾਂ ਪਹਿਲਾਂ ਹੀ ਸੂਚੀਬੱਧ ਹਨ।",
  "Provision updated.": "ਧਾਰਾ ਅੱਪਡੇਟ ਕੀਤੀ ਗਈ।",
