  "A short paraphrase, not the statutory text.": "ਛੋਟਾ ਭਾਵਾਰਥ, ਕਾਨੂੰਨੀ ਪਾਠ ਨਹੀਂ।",
  "Trigger phrases": "ਟ੍ਰਿਗਰ ਵਾਕਾਂਸ਼",
  "One per line or comma-separated, in any language. A suggestion appears when one of these phrases is in the statement.": "ਹਰ ਲਾਈਨ ਵਿੱਚ ਇੱਕ ਜਾਂ ਕੌਮੇ ਨਾਲ ਵੱਖ ਕੀਤੇ, ਕਿਸੇ ਵੀ ਭਾਸ਼ਾ ਵਿੱਚ। ਜਦੋਂ ਇਨ੍ਹਾਂ ਵਿੱਚੋਂ ਕੋਈ ਵਾਕਾਂਸ਼ ਬਿਆਨ ਵਿੱਚ ਹੁੰਦਾ ਹੈ ਤਾਂ ਸੁਝਾਅ ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ।",
  "Source note": "ਸਰੋਤ ਨੋਟ",
  "Where this entry was verified, or what still needs checking.": "ਇਸ ਐਂਟਰੀ ਦੀ ਤਸਦੀਕ ਕਿੱਥੋਂ ਕੀਤੀ ਗਈ, ਜਾਂ ਹਾਲੇ ਕੀ ਜਾਂਚਣਾ ਬਾਕੀ ਹੈ।",
  "Add provision": "ਧਾਰਾ ਜੋੜੋ",
  "Legal provisions catalogue": "ਕਾਨੂੰਨੀ ਧਾਰਾਵਾਂ ਦੀ ਸੂਚੀ",
  "The list the system draws suggestions from. Suggestions are only ever shown to officers, who decide what applies.": "ਉਹ ਸੂਚੀ ਜਿਸ ਤੋਂ ਸਿਸਟਮ ਸੁਝਾਅ ਲੈਂਦਾ ਹੈ। ਸੁਝਾਅ ਸਿਰਫ਼ ਅਧਿਕਾਰੀਆਂ ਨੂੰ ਹੀ ਦਿਖਾਏ ਜਾਂਦੇ ਹਨ, ਜੋ ਤੈਅ ਕਰਦੇ ਹਨ ਕਿ ਕੀ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।",
  "Verify every entry against the official text": "ਹਰ ਐਂਟਰੀ ਦੀ ਅਧਿਕਾਰਤ ਪਾਠ ਨਾਲ ਤਸਦੀਕ ਕਰੋ",
  "The starter entries are plain-language summaries prepared for demonstration. Before real use, an authorized person must check each code, title and summary against the official gazetted text.": "ਸ਼ੁਰੂਆਤੀ ਐਂਟਰੀਆਂ ਪ੍ਰਦਰਸ਼ਨ ਲਈ ਤਿਆਰ ਕੀਤੇ ਸਰਲ-ਭਾਸ਼ਾ ਸਾਰ ਹਨ। ਅਸਲ ਵਰਤੋਂ ਤੋਂ ਪਹਿਲਾਂ, ਕਿਸੇ ਅਧਿਕਾਰਤ ਵਿਅਕਤੀ ਨੂੰ ਹਰ ਕੋਡ, ਸਿਰਲੇਖ ਅਤੇ ਸਾਰ ਦੀ ਅਧਿਕਾਰਤ ਗਜ਼ਟ ਪਾਠ ਨਾਲ ਜਾਂਚ ਕਰਨੀ ਲਾਜ਼ਮੀ ਹੈ।",
  "Provisions ({count})": "ਧਾਰਾਵਾਂ ({count})",
  "Search provisions": "ਧਾਰਾਵਾਂ ਖੋਜੋ",
  "Search code, title or summary": "ਕੋਡ, ਸਿਰਲੇਖ ਜਾਂ ਸਾਰ ਖੋਜੋ",
