  "Location is too long": "ਸਥਾਨ ਬਹੁਤ ਲੰਮਾ ਹੈ",
  "Describe what happened (at least 30 characters)": "ਦੱਸੋ ਕਿ ਕੀ ਹੋਇਆ (ਘੱਟੋ-ਘੱਟ 30 ਅੱਖਰ)",
  "Description is too long (8,000 characters max)": "ਵੇਰਵਾ ਬਹੁਤ ਲੰਮਾ ਹੈ (ਵੱਧ ਤੋਂ ਵੱਧ 8,000 ਅੱਖਰ)",
  "Please confirm the declaration to submit": "ਜਮ੍ਹਾਂ ਕਰਨ ਲਈ ਕਿਰਪਾ ਕਰਕੇ ਘੋਸ਼ਣਾ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ",
  "Please correct the highlighted fields.": "ਕਿਰਪਾ ਕਰਕੇ ਉਜਾਗਰ ਕੀਤੇ ਖੇਤਰ ਠੀਕ ਕਰੋ।",
  "Something went wrong. Your complaint was not saved. Please try again.": "ਕੁਝ ਗ਼ਲਤ ਹੋ ਗਿਆ। ਤੁਹਾਡੀ ਸ਼ਿਕਾਇਤ ਸੇਵ ਨਹੀਂ ਹੋਈ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Too many complaints have been submitted from this connection. Please try again later.": "ਇਸ ਕਨੈਕਸ਼ਨ ਤੋਂ ਬਹੁਤ ਜ਼ਿਆਦਾ ਸ਼ਿਕਾਇਤਾਂ ਜਮ੍ਹਾਂ ਕੀਤੀਆਂ ਗਈਆਂ ਹਨ। ਕਿਰਪਾ ਕਰਕੇ ਬਾਅਦ ਵਿੱਚ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Too many lookups. Please wait a few minutes and try again.": "ਬਹੁਤ ਜ਼ਿਆਦਾ ਖੋਜਾਂ। ਕਿਰਪਾ ਕਰਕੇ ਕੁਝ ਮਿੰਟ ਉਡੀਕ ਕਰੋ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Enter the tracking code and the phone number you used.": "ਟ੍ਰੈਕਿੰਗ ਕੋਡ ਅਤੇ ਤੁਹਾਡੇ ਵੱਲੋਂ ਵਰਤਿਆ ਫ਼ੋਨ ਨੰਬਰ ਦਰਜ ਕਰੋ।",
  "Submitted": "ਜਮ੍ਹਾਂ ਕੀਤੀ",
  "Under verification": "ਤਸਦੀਕ ਅਧੀਨ",
  "Verified": "ਤਸਦੀਕ ਹੋ ਗਈ",
  "Not accepted": "ਸਵੀਕਾਰ ਨਹੀਂ ਕੀਤੀ",
  "Duplicate": "ਦੁਹਰਾਅ",
  "Case opened": "ਕੇਸ ਖੋਲ੍ਹਿਆ ਗਿਆ",
  "Your complaint has been received. Police staff will verify it and contact you.": "ਤੁਹਾਡੀ ਸ਼ਿਕਾਇਤ ਪ੍ਰਾਪਤ ਹੋ ਗਈ ਹੈ। ਪੁਲਿਸ ਸਟਾਫ਼ ਇਸ ਦੀ ਤਸਦੀਕ ਕਰੇਗਾ ਅਤੇ ਤੁਹਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੇਗਾ।",
  "Police staff are verifying your complaint. You may be contacted for details.": "ਪੁਲਿਸ ਸਟਾਫ਼ ਤੁਹਾਡੀ ਸ਼ਿਕਾਇਤ ਦੀ ਤਸਦੀਕ ਕਰ ਰਿਹਾ ਹੈ। ਵੇਰਵਿਆਂ ਲਈ ਤੁਹਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।",
  "Your complaint has been verified. Staff will contact you about next steps.": "ਤੁਹਾਡੀ ਸ਼ਿਕਾਇਤ ਦੀ ਤਸਦੀਕ ਹੋ ਗਈ ਹੈ। ਅਗਲੇ ਕਦਮਾਂ ਬਾਰੇ ਸਟਾਫ਼ ਤੁਹਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੇਗਾ।",
  "Your complaint could not be accepted online. Please see the note from the station.": "ਤੁਹਾਡੀ ਸ਼ਿਕਾਇਤ ਔਨਲਾਈਨ ਸਵੀਕਾਰ ਨਹੀਂ ਕੀਤੀ ਜਾ ਸਕੀ। ਕਿਰਪਾ ਕਰਕੇ ਥਾਣੇ ਵੱਲੋਂ ਦਿੱਤਾ ਨੋਟ ਵੇਖੋ।",
  "Your complaint matches a matter the station is already handling.": "ਤੁਹਾਡੀ ਸ਼ਿਕਾਇਤ ਉਸ ਮਾਮਲੇ ਨਾਲ ਮੇਲ ਖਾਂਦੀ ਹੈ ਜਿਸ 'ਤੇ ਥਾਣਾ ਪਹਿਲਾਂ ਹੀ ਕਾਰਵਾਈ ਕਰ ਰਿਹਾ ਹੈ।",
  "The station has opened a case for your complaint. Staff will contact you.": "ਥਾਣੇ ਨੇ ਤੁਹਾਡੀ ਸ਼ਿਕਾਇਤ ਲਈ ਕੇਸ ਖੋਲ੍ਹਿਆ ਹੈ। ਸਟਾਫ਼ ਤੁਹਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੇਗਾ।",
  "Online Complaints": "ਔਨਲਾਈਨ ਸ਼ਿਕਾਇਤਾਂ",
  "Online complaint": "ਔਨਲਾਈਨ ਸ਼ਿਕਾਇਤ",
  "Complaints submitted by the public through the online form. Verify each one before opening a case. A submission is not a registered FIR.": "ਜਨਤਾ ਵੱਲੋਂ ਔਨਲਾਈਨ ਫ਼ਾਰਮ ਰਾਹੀਂ ਜਮ੍ਹਾਂ ਕੀਤੀਆਂ ਸ਼ਿਕਾਇਤਾਂ। ਕੇਸ ਖੋਲ੍ਹਣ ਤੋਂ ਪਹਿਲਾਂ ਹਰ ਇੱਕ ਦੀ ਤਸਦੀਕ ਕਰੋ। ਜਮ੍ਹਾਂ ਕੀਤੀ ਸ਼ਿਕਾਇਤ ਦਰਜ ਕੀਤੀ FIR ਨਹੀਂ ਹੈ।",
  "Open public form": "ਜਨਤਕ ਫ਼ਾਰਮ ਖੋਲ੍ਹੋ",
  "Needs action": "ਕਾਰਵਾਈ ਦੀ ਲੋੜ",
  "Search by tracking code or name": "ਟ੍ਰੈਕਿੰਗ ਕੋਡ ਜਾਂ ਨਾਮ ਨਾਲ ਖੋਜੋ",
  "No online complaints here": "ਇੱਥੇ ਕੋਈ ਔਨਲਾਈਨ ਸ਼ਿਕਾਇਤ ਨਹੀਂ",
  "New submissions from the public form appear in this queue.": "ਜਨਤਕ ਫ਼ਾਰਮ ਤੋਂ ਨਵੀਆਂ ਸ਼ਿਕਾਇਤਾਂ ਇਸ ਕਤਾਰ ਵਿੱਚ ਦਿਖਾਈ ਦਿੰਦੀਆਂ ਹਨ।",
  "Incident": "ਘਟਨਾ",
  "Complaint": "ਸ਼ਿਕਾਇਤ",
  "Submitted online by the complainant. Not a registered FIR; verify before acting.": "ਸ਼ਿਕਾਇਤਕਰਤਾ ਵੱਲੋਂ ਔਨਲਾਈਨ ਜਮ੍ਹਾਂ ਕੀਤੀ। ਦਰਜ ਕੀਤੀ FIR ਨਹੀਂ; ਕਾਰਵਾਈ ਤੋਂ ਪਹਿਲਾਂ ਤਸਦੀਕ ਕਰੋ।",
