  "Open a case from this complaint?": "ਕੀ ਇਸ ਸ਼ਿਕਾਇਤ ਤੋਂ ਕੇਸ ਖੋਲ੍ਹਣਾ ਹੈ?",
  "A local case will be opened with the complaint as a typed statement marked “submitted online, not yet confirmed in person”. This does not register an FIR.": "ਇੱਕ ਸਥਾਨਕ ਕੇਸ ਖੋਲ੍ਹਿਆ ਜਾਵੇਗਾ ਜਿਸ ਵਿੱਚ ਸ਼ਿਕਾਇਤ ਨੂੰ ਟਾਈਪ ਕੀਤੇ ਬਿਆਨ ਵਜੋਂ “ਔਨਲਾਈਨ ਜਮ੍ਹਾਂ ਕੀਤੀ, ਹਾਲੇ ਨਿੱਜੀ ਤੌਰ 'ਤੇ ਪੁਸ਼ਟੀ ਨਹੀਂ ਹੋਈ” ਚਿੰਨ੍ਹਿਤ ਕੀਤਾ ਜਾਵੇਗਾ। ਇਸ ਨਾਲ FIR ਦਰਜ ਨਹੀਂ ਹੁੰਦੀ।",
  "Assign case to": "ਕੇਸ ਕਿਸ ਨੂੰ ਸੌਂਪਣਾ ਹੈ",
  "Open case and start work": "ਕੇਸ ਖੋਲ੍ਹੋ ਅਤੇ ਕੰਮ ਸ਼ੁਰੂ ਕਰੋ",
