  "Archive this update?": "ਕੀ ਇਹ ਅੱਪਡੇਟ ਪੁਰਾਲੇਖ ਵਿੱਚ ਪਾਉਣਾ ਹੈ?",
  "Archived updates are hidden from staff. Only publishers can see this list.": "ਪੁਰਾਲੇਖ ਵਿੱਚ ਪਾਏ ਅੱਪਡੇਟ ਸਟਾਫ਼ ਤੋਂ ਲੁਕੇ ਰਹਿੰਦੇ ਹਨ। ਸਿਰਫ਼ ਪ੍ਰਕਾਸ਼ਕ ਹੀ ਇਹ ਸੂਚੀ ਵੇਖ ਸਕਦੇ ਹਨ।",
  "Archived updates are hidden from staff. This cannot be undone from the app.": "ਪੁਰਾਲੇਖ ਵਿੱਚ ਪਾਏ ਅੱਪਡੇਟ ਸਟਾਫ਼ ਤੋਂ ਲੁਕੇ ਰਹਿੰਦੇ ਹਨ। ਇਸ ਨੂੰ ਐਪ ਤੋਂ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।",
  "Acknowledged": "ਪੜ੍ਹਨ ਦੀ ਪੁਸ਼ਟੀ ਕੀਤੀ",
  "Acknowledgement required": "ਪੜ੍ਹਨ ਦੀ ਪੁਸ਼ਟੀ ਲਾਜ਼ਮੀ",
