  "Circular / notification number or link": "ਸਰਕੂਲਰ / ਨੋਟੀਫ਼ਿਕੇਸ਼ਨ ਨੰਬਰ ਜਾਂ ਲਿੰਕ",
  "Each recipient must confirm they have read and understood it. You can see who hasn't.": "ਹਰ ਪ੍ਰਾਪਤਕਰਤਾ ਨੂੰ ਪੁਸ਼ਟੀ ਕਰਨੀ ਲਾਜ਼ਮੀ ਹੈ ਕਿ ਉਸ ਨੇ ਇਸ ਨੂੰ ਪੜ੍ਹ ਅਤੇ ਸਮਝ ਲਿਆ ਹੈ। ਤੁਸੀਂ ਵੇਖ ਸਕਦੇ ਹੋ ਕਿ ਕਿਸ ਨੇ ਨਹੀਂ ਕੀਤੀ।",
  "Edit update": "ਅੱਪਡੇਟ ਸੋਧੋ",
  "Edits are recorded in the audit log. Recipients are not notified again.": "ਸੋਧਾਂ ਆਡਿਟ ਲੌਗ ਵਿੱਚ ਦਰਜ ਹੁੰਦੀਆਂ ਹਨ। ਪ੍ਰਾਪਤਕਰਤਾਵਾਂ ਨੂੰ ਦੁਬਾਰਾ ਸੂਚਿਤ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ।",
  "Effective date": "ਲਾਗੂ ਹੋਣ ਦੀ ਮਿਤੀ",
