  "Last edited": "ਆਖ਼ਰੀ ਵਾਰ ਸੋਧਿਆ",
  "New rules, circulars and announcements published for your station will appear here.": "ਤੁਹਾਡੇ ਥਾਣੇ ਲਈ ਪ੍ਰਕਾਸ਼ਿਤ ਨਵੇਂ ਨਿਯਮ, ਸਰਕੂਲਰ ਅਤੇ ਘੋਸ਼ਣਾਵਾਂ ਇੱਥੇ ਦਿਖਾਈ ਦੇਣਗੀਆਂ।",
  "New rules, circulars, advisories and system updates for your station. Summaries are for staff awareness — always refer to the official source.": "ਤੁਹਾਡੇ ਥਾਣੇ ਲਈ ਨਵੇਂ ਨਿਯਮ, ਸਰਕੂਲਰ, ਸਲਾਹਾਂ ਅਤੇ ਸਿਸਟਮ ਅੱਪਡੇਟ। ਸਾਰ ਸਟਾਫ਼ ਦੀ ਜਾਣਕਾਰੀ ਲਈ ਹਨ — ਹਮੇਸ਼ਾ ਅਧਿਕਾਰਤ ਸਰੋਤ ਵੇਖੋ।",
  "No archived updates": "ਪੁਰਾਲੇਖ ਵਿੱਚ ਕੋਈ ਅੱਪਡੇਟ ਨਹੀਂ",
