  "Pin to top": "ਸਿਖਰ 'ਤੇ ਪਿੰਨ ਕਰੋ",
  "Pinned updates stay above newer ones until archived.": "ਪਿੰਨ ਕੀਤੇ ਅੱਪਡੇਟ ਪੁਰਾਲੇਖ ਵਿੱਚ ਪਾਏ ਜਾਣ ਤੱਕ ਨਵੇਂ ਅੱਪਡੇਟਾਂ ਤੋਂ ਉੱਪਰ ਰਹਿੰਦੇ ਹਨ।",
  "Pinned": "ਪਿੰਨ ਕੀਤਾ",
  "Plain text. Line breaks are kept. Summarise the rule for staff and cite the official source in Reference — this is not the official text.": "ਸਾਦਾ ਪਾਠ। ਲਾਈਨ ਬ੍ਰੇਕ ਬਰਕਰਾਰ ਰਹਿੰਦੇ ਹਨ। ਸਟਾਫ਼ ਲਈ ਨਿਯਮ ਦਾ ਸਾਰ ਲਿਖੋ ਅਤੇ ਹਵਾਲੇ ਵਿੱਚ ਅਧਿਕਾਰਤ ਸਰੋਤ ਦੱਸੋ — ਇਹ ਅਧਿਕਾਰਤ ਪਾਠ ਨਹੀਂ ਹੈ।",
