  "Share a new rule, circular, advisory or system update. Every recipient is notified.": "ਨਵਾਂ ਨਿਯਮ, ਸਰਕੂਲਰ, ਸਲਾਹ ਜਾਂ ਸਿਸਟਮ ਅੱਪਡੇਟ ਸਾਂਝਾ ਕਰੋ। ਹਰ ਪ੍ਰਾਪਤਕਰਤਾ ਨੂੰ ਸੂਚਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
  "Station administrators can publish only to their own station.": "ਥਾਣਾ ਪ੍ਰਸ਼ਾਸਕ ਸਿਰਫ਼ ਆਪਣੇ ਥਾਣੇ ਲਈ ਹੀ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰ ਸਕਦੇ ਹਨ।",
  "The title appears in every recipient's notifications.": "ਸਿਰਲੇਖ ਹਰ ਪ੍ਰਾਪਤਕਰਤਾ ਦੀਆਂ ਸੂਚਨਾਵਾਂ ਵਿੱਚ ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ।",
  "This summary is for staff awareness and is not the official text. Refer to the cited source.": "ਇਹ ਸਾਰ ਸਟਾਫ਼ ਦੀ ਜਾਣਕਾਰੀ ਲਈ ਹੈ ਅਤੇ ਅਧਿਕਾਰਤ ਪਾਠ ਨਹੀਂ ਹੈ। ਦੱਸਿਆ ਗਿਆ ਸਰੋਤ ਵੇਖੋ।",
  "Visible to publishers only.": "ਸਿਰਫ਼ ਪ੍ਰਕਾਸ਼ਕਾਂ ਨੂੰ ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ।",
  "Write a clear summary for staff and cite the official source. Do not include personal details or case information.": "ਸਟਾਫ਼ ਲਈ ਸਪਸ਼ਟ ਸਾਰ ਲਿਖੋ ਅਤੇ ਅਧਿਕਾਰਤ ਸਰੋਤ ਦੱਸੋ। ਨਿੱਜੀ ਵੇਰਵੇ ਜਾਂ ਕੇਸ ਦੀ ਜਾਣਕਾਰੀ ਸ਼ਾਮਲ ਨਾ ਕਰੋ।",
